#!/bin/bash
echo "Restoring valid AppIcon and MellButton PNGs from base64..."

cat << 'B64EOF' | base64 --decode > MellClicker/Resources/Assets.xcassets/MellButton.imageset/MellButton.png

B64EOF

cp MellClicker/Resources/Assets.xcassets/MellButton.imageset/MellButton.png MellClicker/Resources/Assets.xcassets/MellButton.imageset/MellButton@2x.png
cp MellClicker/Resources/Assets.xcassets/MellButton.imageset/MellButton.png MellClicker/Resources/Assets.xcassets/MellButton.imageset/MellButton@3x.png

cat << 'B64EOF' | base64 --decode > MellClicker/Resources/Assets.xcassets/AppIcon.appiconset/icon_1024x1024@1x.png

B64EOF

# Generate required icon sizes for Xcode
cat << 'PYSCRIPT' > gen.py
import subprocess
import os

sizes = [
    (20, 2, "iphone"), (20, 3, "iphone"), (29, 2, "iphone"), (29, 3, "iphone"),
    (40, 2, "iphone"), (40, 3, "iphone"), (60, 2, "iphone"), (60, 3, "iphone"),
    (20, 1, "ipad"), (20, 2, "ipad"), (29, 1, "ipad"), (29, 2, "ipad"),
    (40, 1, "ipad"), (40, 2, "ipad"), (76, 1, "ipad"), (76, 2, "ipad"),
    (83.5, 2, "ipad")
]

src = "MellClicker/Resources/Assets.xcassets/AppIcon.appiconset/icon_1024x1024@1x.png"
base_dir = "MellClicker/Resources/Assets.xcassets/AppIcon.appiconset"
import json

images = [{"size":"1024x1024","idiom":"ios-marketing","filename":"icon_1024x1024@1x.png","scale":"1x"}]

for (s, scale, idiom) in sizes:
    dim = int(s * scale)
    filename = f"icon_{s}x{s}@{scale}x.png"
    # we use sips in macOS runner
    subprocess.run(["sips", "-z", str(dim), str(dim), src, "--out", os.path.join(base_dir, filename)])
    size_str = str(s)
    if s == int(s):
        size_str = str(int(s))
    images.append({
        "size": f"{size_str}x{size_str}",
        "idiom": idiom,
        "filename": filename,
        "scale": f"{scale}x"
    })

with open(f"{base_dir}/Contents.json", "w") as f:
    json.dump({"images": images, "info": {"version":1,"author":"xcode"}}, f, indent=2)

PYSCRIPT
python3 gen.py

echo "Asset restoration complete!"
